import { expectNoContent, readJson, send, type FetchLike } from './http'
import type { WebKakaoAuthorization, WebSession } from './types'

/**
 * Cookie-based web auth (A2, /api/v1/auth/web/*). The refresh token never reaches this code:
 * the server keeps it in an HttpOnly cookie. Every call carries the CSRF client header; the
 * browser adds Origin itself. state and nonce are generated by the server, never here.
 */
export const WEB_CLIENT_HEADERS = { 'X-NurseFlow-Client': 'web' } as const

export interface AuthApi {
  startKakaoLogin(redirectUri: string): Promise<WebKakaoAuthorization>
  exchangeCode(code: string, state: string): Promise<WebSession>
  refresh(): Promise<WebSession>
  logout(): Promise<void>
}

export function createAuthApi(fetchImpl: FetchLike): AuthApi {
  const post = (path: string, body?: unknown) =>
    send(fetchImpl, `/auth/web${path}`, {
      method: 'POST',
      headers: body === undefined ? { ...WEB_CLIENT_HEADERS } : { ...WEB_CLIENT_HEADERS, 'Content-Type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
    })

  return {
    startKakaoLogin: async (redirectUri) => readJson(await post('/kakao/authorization', { redirectUri })),
    exchangeCode: async (code, state) => readJson(await post('/kakao/code', { code, state })),
    refresh: async () => readJson(await post('/session/refresh')),
    logout: async () => expectNoContent(await post('/logout')),
  }
}
